prompt:
Task: engineering analysis
Role: cto
Scope: agents/**
task_id: task-1:cto
assigned_role: cto
Expected output: structured TaskResult JSON
Reply with EXACTLY ONE JSON object, no markdown, no extra text, conforming to:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "task_id",
    "assigned_role",
    "status",
    "confidence",
    "reported_at"
  ],
  "properties": {
    "task_id": {
      "type": "string",
      "minLength": 1
    },
    "assigned_role": {
      "enum": [
        "zeko",
        "cto",
        "cfo",
        "kai",
        "somad",
        "badsector",
        "nova"
      ]
    },
    "status": {
      "enum": [
        "SUCCEEDED",
        "FAILED",
        "BLOCKED"
      ]
    },
    "findings": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "evidence": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "assumptions": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "risks": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "recommendation": {
      "type": "string"
    },
    "confidence": {
      "enum": [
        "LOW",
        "MEDIUM",
        "HIGH"
      ]
    },
    "unresolved_items": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "actions_taken": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "reported_at": {
      "type": "string",
      "format": "date-time"
    }
  }
}
